const lockRunningImproverPass = `-- name: LockRunningImproverPass :one
UPDATE improver_passes SET alive_at = now()
WHERE id = $1 AND status = 'running'
RETURNING id
`

// The pass, held while a proposal is stored and marked alive, so it is
// not failed as lost in between or just after. No row when it is no
// longer running.
func (q *Queries) LockRunningImproverPass(ctx context.Context, id uuid.UUID) (uuid.UUID, error) {
	row := q.db.QueryRow(ctx, lockRunningImproverPass, id)
	var id_2 uuid.UUID
	err := row.Scan(&id_2)
	return id_2, err
}

const touchImproverPass = `-- name: TouchImproverPass :execrows
UPDATE improver_passes SET alive_at = now(), drew_on = $1
WHERE id = $2 AND status = 'running'
`

type TouchImproverPassParams struct {
	DrewOn []uuid.UUID
	ID     uuid.UUID
}

// An attempt beginning: the pass is alive, and draws on these runs. No row
// when it is no longer running: failed as lost meanwhile.
func (q *Queries) TouchImproverPass(ctx context.Context, arg TouchImproverPassParams) (int64, error) {
	result, err := q.db.Exec(ctx, touchImproverPass, arg.DrewOn, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const withdrawSupersededProposals = `-- name: WithdrawSupersededProposals :exec
UPDATE improvement_proposals
SET status = 'withdrawn', withdrawn_by = $1
WHERE team_id = $2 AND agent_id = $3 AND status = 'waiting'
  AND id <> $1 AND pass_id IS NOT NULL
  AND kind = $4 AND signature = $5
  AND skill_id IS NOT DISTINCT FROM $6::uuid
`

type WithdrawSupersededProposalsParams struct {
	NewerID   *uuid.UUID
	TeamID    uuid.UUID
	AgentID   uuid.UUID
	Kind      string
	Signature *string
	SkillID   *uuid.UUID
}

// What an earlier pass left waiting on the same pattern, the same kind and
// the same target, which a newer proposal replaces. A person's own, and a
// pass's on another pattern, wait on.
func (q *Queries) WithdrawSupersededProposals(ctx context.Context, arg WithdrawSupersededProposalsParams) error {
	_, err := q.db.Exec(ctx, withdrawSupersededProposals,
		arg.NewerID,
		arg.TeamID,
		arg.AgentID,
		arg.Kind,
		arg.Signature,
		arg.SkillID,
	)
	return err
}
